// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/home", wrapper.GetHome)
	router.GET(options.BaseURL+"/categories", wrapper.ListCategories)
	router.GET(options.BaseURL+"/packages", wrapper.ListPackages)
	router.GET(options.BaseURL+"/packages/:kind/:token", wrapper.GetPackage)
	router.GET(options.BaseURL+"/packages/:kind/:token/releases", wrapper.ListPackageReleases)
	router.GET(options.BaseURL+"/packages/:kind/:token/dependencies", wrapper.GetPackageDependencies)
	router.GET(options.BaseURL+"/packages/:kind/:token/related", wrapper.ListRelatedPackages)
	router.POST(options.BaseURL+"/packages/lookup", wrapper.LookupPackages)
	router.GET(options.BaseURL+"/search", wrapper.SearchPackages)
	router.GET(options.BaseURL+"/search/suggest", wrapper.Suggest)
	router.POST(options.BaseURL+"/search/clicks", wrapper.ReportSearchClick)
	router.GET(options.BaseURL+"/rankings", wrapper.ListRankings)
	router.GET(options.BaseURL+"/collections", wrapper.ListCollections)
	router.GET(options.BaseURL+"/collections/:slug", wrapper.GetCollection)
	router.GET(options.BaseURL+"/collections/:slug/brewfile", wrapper.GetCollectionBrewfile)
	router.GET(options.BaseURL+"/catalog/snapshot", wrapper.GetCatalogSnapshot)
	router.GET(options.BaseURL+"/catalog/changes", wrapper.ListCatalogChanges)
	router.GET(options.BaseURL+"/config/client", wrapper.GetClientConfig)
	router.GET(options.BaseURL+"/desktop/releases/latest", wrapper.GetLatestDesktopRelease)
	router.POST(options.BaseURL+"/feedback", wrapper.CreateFeedback)
	router.GET(options.BaseURL+"/sitemap/packages", wrapper.ListSitemapPackages)
}

